{
  "root": "main",
  "state": {
    "itinerary": [
      { "day": "Apr 10", "pace": "Light arrival day", "focus": "Central Kyoto, Nishiki Market, Gion evening", "walking": "Low", "notes": "Easy start after travel; keep dinner nearby" },
      { "day": "Apr 11", "pace": "Full temple day", "focus": "Higashiyama, Kiyomizu-dera, Kodai-ji", "walking": "Medium", "notes": "Start early to avoid crowds" },
      { "day": "Apr 12", "pace": "Low-walking day", "focus": "Arashiyama by taxi + scenic viewpoints", "walking": "Low", "notes": "Best day for the grandparent; use taxis and short stops" },
      { "day": "Apr 13", "pace": "Temple + food day", "focus": "Northern Kyoto, Daitoku-ji area, local lunch spots", "walking": "Medium", "notes": "Good mix of quieter temples and neighborhood food" },
      { "day": "Apr 14", "pace": "Flexible cultural day", "focus": "Fushimi Inari early or Kyoto Imperial area", "walking": "Medium", "notes": "Choose based on energy and weather" },
      { "day": "Apr 15", "pace": "Departure day", "focus": "Short breakfast and easy transfer", "walking": "Very low", "notes": "Keep this mostly open" }
    ],
    "budget": [
      { "category": "Lodging", "amount": "$1,450", "share": "45%", "why": "Family room, apartment, or 2 connected rooms" },
      { "category": "Food", "amount": "$950", "share": "30%", "why": "Mix of casual lunches and nicer dinners" },
      { "category": "Transit", "amount": "$250", "share": "8%", "why": "IC cards, taxis, and train/bus rides" },
      { "category": "Activities", "amount": "$350", "share": "11%", "why": "Temple fees, gardens, museum stops" },
      { "category": "Buffer", "amount": "$200", "share": "6%", "why": "Unexpected costs" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "summary", "itineraryTable", "budgetTable", "actions"]
    },
    "title": { "type": "Text", "props": { "text": "Kyoto Family Trip Plan (April 10–15, 2026)", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "A 6-day Kyoto trip for a family of four with a $3,200 budget. Focus on clustered temple visits and central lodging for maximum comfort.", "variant": "body" }, "children": [] },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "title": "Daily Pace and Structure",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "statePath": "/itinerary",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "pace", "label": "Pace" },
          { "key": "focus", "label": "Focus" },
          { "key": "walking", "label": "Walking" }
        ]
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "title": "Recommended Budget Split",
        "domain": "generic",
        "preferredPresentation": "table",
        "statePath": "/budget",
        "columns": [
          { "key": "category", "label": "Category" },
          { "key": "amount", "label": "Amount" },
          { "key": "share", "label": "Share" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Build stay shortlist", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.booking.com/city/jp/kyoto.html" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Kyoto transit map", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.jrpass.com/map/kyoto" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Temple area guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e3932.html" } } } }, "children": [] }
  }
}
